"""Order fulfillment JSON CLI entry point."""

from __future__ import annotations

import argparse
import json
import sys
import time
import uuid

from src.order_fulfillment import OrderError, OrderService

_VALID_COMMANDS = frozenset({"stock", "create", "pay", "cancel", "ship", "get"})
_COMMANDS_NO_INPUT = frozenset({"get"})  # but they still consume stdin, just order_id is in the input


def _read_input() -> dict:
    """Read one JSON object from stdin; treat empty input as {}."""
    raw = sys.stdin.read()
    if not raw.strip():
        return {}
    try:
        obj = json.loads(raw)
    except json.JSONDecodeError as exc:
        _fail("INVALID_INPUT", f"Invalid JSON: {exc}")
        # unreachable – _fail raises
        return {}
    if not isinstance(obj, dict):
        _fail("INVALID_INPUT", "Input must be a JSON object")
    return obj  # type: ignore[return-value]


def _ok(result: object) -> None:
    payload = json.dumps(
        {"ok": True, "result": result},
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )
    sys.stdout.write(payload + "\n")
    sys.stdout.flush()


def _fail(code: str, message: str, details: dict | None = None, exit_code: int = 2) -> None:
    payload = json.dumps(
        {
            "ok": False,
            "error": {
                "code": code,
                "message": message,
                "details": details if details is not None else {},
            },
        },
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )
    sys.stdout.write(payload + "\n")
    sys.stdout.flush()
    sys.exit(exit_code)


def main() -> None:
    parser = argparse.ArgumentParser(prog="python -m src.order_fulfillment")
    parser.add_argument("--db", required=True, help="Path to SQLite database")
    parser.add_argument("command", help="One of: stock, create, pay, cancel, ship, get")
    args = parser.parse_args()

    if args.command not in _VALID_COMMANDS:
        _fail("INVALID_INPUT", f"Unknown command: {args.command}")

    try:
        svc = OrderService(
            args.db,
            clock=time.time,
            id_factory=lambda: uuid.uuid4().hex,
        )
    except OrderError as exc:
        _fail(exc.code, exc.message, exc.details)

    data = _read_input()

    try:
        if args.command == "stock":
            sku = data.get("sku")
            quantity = data.get("quantity")
            if sku is None or quantity is None:
                _fail("INVALID_INPUT", "Missing required fields: sku, quantity")
            result = svc.set_stock(sku, quantity)
        elif args.command == "create":
            idempotency_key = data.get("idempotency_key")
            items = data.get("items")
            if idempotency_key is None or items is None:
                _fail("INVALID_INPUT", "Missing required fields: idempotency_key, items")
            result = svc.create_order(idempotency_key, items)
        elif args.command == "pay":
            order_id = data.get("order_id")
            payment_id = data.get("payment_id")
            amount_cents = data.get("amount_cents")
            if order_id is None or payment_id is None or amount_cents is None:
                _fail("INVALID_INPUT", "Missing required fields: order_id, payment_id, amount_cents")
            result = svc.pay_order(order_id, payment_id, amount_cents)
        elif args.command in ("cancel", "ship", "get"):
            order_id = data.get("order_id")
            if order_id is None:
                _fail("INVALID_INPUT", "Missing required field: order_id")
            if args.command == "cancel":
                result = svc.cancel_order(order_id)
            elif args.command == "ship":
                result = svc.ship_order(order_id)
            else:
                result = svc.get_order(order_id)
        else:
            _fail("INVALID_INPUT", f"Unknown command: {args.command}")
    except OrderError as exc:
        _fail(exc.code, exc.message, exc.details)
    except Exception:
        _fail("STORAGE_ERROR", "Unexpected storage error", exit_code=3)

    _ok(result)


if __name__ == "__main__":
    main()

