"""Delivery spool – filesystem-backed durable outbox / lease queue."""

from __future__ import annotations

import dataclasses
import hashlib
import json
import os
import secrets
import sys
import tempfile
import time
from math import isfinite
from typing import Any


# ---------------------------------------------------------------------------
# Limits
# ---------------------------------------------------------------------------

@dataclasses.dataclass(frozen=True)
class Limits:
    max_messages: int = 10000
    max_payload_bytes: int = 65536
    max_attempts: int = 5
    lease_seconds: float = 30.0
    retry_delay: float = 10.0

    def __post_init__(self) -> None:
        for name in ("max_messages", "max_payload_bytes", "max_attempts"):
            v = getattr(self, name)
            if isinstance(v, bool) or not isinstance(v, int) or v <= 0:
                raise SpoolError("INVALID_INPUT", f"{name} must be a positive integer")
        for name in ("lease_seconds", "retry_delay"):
            v = getattr(self, name)
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise SpoolError("INVALID_INPUT", f"{name} must be a finite number")
            if not isfinite(v):
                raise SpoolError("INVALID_INPUT", f"{name} must be finite")
            if v < 0:
                raise SpoolError("INVALID_INPUT", f"{name} must be >= 0")
        if self.lease_seconds <= 0:
            raise SpoolError("INVALID_INPUT", "lease_seconds must be > 0")


# ---------------------------------------------------------------------------
# SpoolError
# ---------------------------------------------------------------------------

_STABLE_CODES = frozenset({
    "INVALID_INPUT",
    "INVALID_DEPENDENCY",
    "NOT_INITIALIZED",
    "ALREADY_INITIALIZED",
    "NOT_FOUND",
    "IDEMPOTENCY_CONFLICT",
    "CAPACITY_EXCEEDED",
    "UNAUTHORIZED",
    "INVALID_STATE",
    "CORRUPT_STATE",
    "SCHEMA_MISMATCH",
    "LOCK_TIMEOUT",
    "INTERNAL_ERROR",
})

_VALID_STATUSES = frozenset({"pending", "leased", "acked", "dead"})

_SCHEMA_VERSION = 1


class SpoolError(Exception):
    """Stable spool-domain error."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None) -> None:
        super().__init__(message)
        self.code: str = code
        self.message: str = message
        self.details: dict[str, object] = details if details is not None else {}

    def __str__(self) -> str:
        return self.message

    def __repr__(self) -> str:
        return f"SpoolError(code={self.code!r}, message={self.message!r})"


# ---------------------------------------------------------------------------
# Utilities
# ---------------------------------------------------------------------------

def _canonical_json(obj: object) -> str:
    """Serialize to canonical JSON with trailing newline."""
    return (
        json.dumps(
            obj,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
            allow_nan=False,
        )
        + "\n"
    )


_INITIAL_STATE = _canonical_json({
    "schema_version": _SCHEMA_VERSION,
    "next_sequence": 1,
    "messages": {},
})


def _is_nonempty_string(s: object) -> bool:
    if not isinstance(s, str):
        return False
    return len(s) > 0 and not s.isspace()


def _is_finite_number(v: object) -> bool:
    if isinstance(v, bool):
        return False
    if isinstance(v, (int, float)):
        return isfinite(v)
    return False


def _validate_payload(payload: object, max_bytes: int) -> bytes:
    """Validate and canonicalize payload. Returns raw UTF-8 bytes."""
    try:
        raw = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)
    except (TypeError, ValueError) as exc:
        raise SpoolError("INVALID_INPUT", f"Payload not JSON-serializable: {exc}")
    encoded = raw.encode("utf-8")
    if len(encoded) > max_bytes:
        raise SpoolError(
            "INVALID_INPUT",
            f"Payload size {len(encoded)} exceeds max {max_bytes} bytes",
        )
    # Detach from caller by round-tripping
    return encoded


def _constant_time_compare(a: str, b: str) -> bool:
    return secrets.compare_digest(a.encode("utf-8"), b.encode("utf-8"))


def _make_public_message(msg_data: dict) -> dict:
    """Return public view of a message, stripping lease_token/worker_id/expires_at."""
    return {
        "message_id": msg_data["message_id"],
        "payload": msg_data["payload"],
        "status": msg_data["status"],
        "available_at": msg_data["available_at"],
        "sequence": msg_data["sequence"],
        "attempts": msg_data["attempts"],
        "last_error": msg_data["last_error"],
    }


def _message_sort_key(msg_data: dict) -> tuple:
    return (msg_data["available_at"], msg_data["sequence"], msg_data["message_id"])


# ---------------------------------------------------------------------------
# Spool
# ---------------------------------------------------------------------------

class Spool:
    """Filesystem-backed lease spool."""

    def __init__(
        self,
        root,
        *,
        clock,
        limits,
        lock_timeout,
        failpoint,
    ) -> None:
        # Validate arguments (no writes)
        if not isinstance(root, str):
            raise SpoolError("INVALID_INPUT", "root must be a string path")
        self._root = root

        if not callable(clock):
            raise SpoolError("INVALID_DEPENDENCY", "clock must be callable")
        self._clock = clock

        if not isinstance(limits, Limits):
            raise SpoolError("INVALID_INPUT", "limits must be a Limits instance")
        self._limits = limits

        if isinstance(lock_timeout, bool) or not isinstance(lock_timeout, (int, float)):
            raise SpoolError("INVALID_INPUT", "lock_timeout must be a finite number")
        if not isfinite(lock_timeout) or lock_timeout < 0:
            raise SpoolError("INVALID_INPUT", "lock_timeout must be >= 0")
        self._lock_timeout = float(lock_timeout)

        if failpoint is not None and not callable(failpoint):
            raise SpoolError("INVALID_INPUT", "failpoint must be callable or None")
        self._failpoint = failpoint

        self._state_path = os.path.join(root, "state.json")
        self._lock_path = os.path.join(root, "state.lock")

    # ---- Lock helpers ----

    def _acquire_lock(self) -> None:
        """Acquire exclusive lock file with timeout."""
        deadline = self._clock() + self._lock_timeout
        while True:
            try:
                fd = os.open(self._lock_path, os.O_CREAT | os.O_EXCL | os.O_RDWR)
                os.close(fd)
                return
            except FileExistsError:
                if self._clock() >= deadline:
                    raise SpoolError("LOCK_TIMEOUT", "Could not acquire lock within timeout")
                # Small backoff
                time.sleep(0.001)

    def _release_lock(self) -> None:
        try:
            os.remove(self._lock_path)
        except FileNotFoundError:
            pass

    def _call_failpoint(self, name: str) -> None:
        if self._failpoint is not None:
            self._failpoint(name)

    # ---- State read/write ----

    def _read_state(self) -> dict:
        """Read and validate state.json. Returns parsed state dict."""
        try:
            with open(self._state_path, "r", encoding="utf-8") as f:
                raw = f.read()
        except FileNotFoundError:
            raise SpoolError("NOT_INITIALIZED", "Spool not initialized; call initialize() first")
        except OSError as exc:
            raise SpoolError("INTERNAL_ERROR", f"Failed to read state: {exc}")

        try:
            state = json.loads(raw)
        except json.JSONDecodeError as exc:
            raise SpoolError("CORRUPT_STATE", f"Malformed JSON in state: {exc}")

        if not isinstance(state, dict):
            raise SpoolError("CORRUPT_STATE", "State root must be an object")

        # Validate top-level fields
        allowed_top = {"schema_version", "next_sequence", "messages"}
        if set(state.keys()) != allowed_top:
            raise SpoolError("CORRUPT_STATE", "State has unexpected top-level keys")

        sv = state.get("schema_version")
        if not isinstance(sv, int) or sv != _SCHEMA_VERSION:
            raise SpoolError(
                "SCHEMA_MISMATCH",
                f"Unknown schema_version: {sv}",
            )

        ns = state.get("next_sequence")
        if isinstance(ns, bool) or not isinstance(ns, int) or ns < 1:
            raise SpoolError("CORRUPT_STATE", "Invalid next_sequence")

        messages = state.get("messages")
        if not isinstance(messages, dict):
            raise SpoolError("CORRUPT_STATE", "messages must be an object")

        for mid, msg in messages.items():
            if not isinstance(mid, str):
                raise SpoolError("CORRUPT_STATE", "Message keys must be strings")
            if not isinstance(msg, dict):
                raise SpoolError("CORRUPT_STATE", f"Message {mid} must be an object")
            _validate_message_data(mid, msg)

        return state

    def _write_state(self, state: dict) -> None:
        """Atomically write state following the durable commit protocol."""
        raw = _canonical_json(state)
        pid = os.getpid()
        # Generate unique temp name
        with tempfile.NamedTemporaryFile(
            mode="w",
            encoding="utf-8",
            dir=self._root,
            prefix=f".state.{pid}.",
            suffix=".tmp",
            delete=False,
        ) as tf:
            tf.write(raw)
            tf.flush()
            os.fsync(tf.fileno())
            tmp_path = tf.name

        try:
            self._call_failpoint("before_replace")
            os.replace(tmp_path, self._state_path)
            self._call_failpoint("after_replace")
            # fsync directory
            try:
                dfd = os.open(self._root, os.O_RDONLY)
                try:
                    os.fsync(dfd)
                finally:
                    os.close(dfd)
            except OSError:
                pass  # best-effort on platforms where it's unsupported
        except BaseException:
            # Clean up temp file on failure
            try:
                os.remove(tmp_path)
            except OSError:
                pass
            raise

        # Clean up any stale temp files
        self._cleanup_temp_files()

    def _cleanup_temp_files(self) -> None:
        """Remove all temp files belonging to this process."""
        pid = os.getpid()
        prefix = f".state.{pid}."
        try:
            for entry in os.listdir(self._root):
                if entry.startswith(prefix) and entry.endswith(".tmp"):
                    try:
                        os.remove(os.path.join(self._root, entry))
                    except OSError:
                        pass
        except OSError:
            pass

    # ---- Public API ----

    def initialize(self) -> dict:
        os.makedirs(self._root, exist_ok=True)
        self._acquire_lock()
        try:
            self._call_failpoint("after_lock")
            if os.path.exists(self._state_path):
                # Already initialized — read and verify
                state = self._read_state()
            else:
                # Create initial state
                state = {
                    "schema_version": _SCHEMA_VERSION,
                    "next_sequence": 1,
                    "messages": {},
                }
                self._write_state(state)
        finally:
            self._release_lock()
        return {"schema_version": state["schema_version"], "next_sequence": state["next_sequence"]}

    def enqueue(self, message_id: str, payload, available_at=None) -> dict:
        if not _is_nonempty_string(message_id):
            raise SpoolError("INVALID_INPUT", "message_id must be a non-empty, non-whitespace string")

        encoded = _validate_payload(payload, self._limits.max_payload_bytes)
        # Re-parse for detached storage
        stored_payload = json.loads(encoded.decode("utf-8"))

        if available_at is None:
            available_at = float(self._validate_clock())
        else:
            if isinstance(available_at, bool) or not isinstance(available_at, (int, float)):
                raise SpoolError("INVALID_INPUT", "available_at must be a finite number")
            if not isfinite(available_at):
                raise SpoolError("INVALID_INPUT", "available_at must be finite")
            available_at = float(available_at)

        self._acquire_lock()
        try:
            self._call_failpoint("after_lock")
            state = self._read_state()

            messages: dict = state["messages"]

            if message_id in messages:
                existing = messages[message_id]
                if isinstance(existing, dict):
                    # Compare payloads and available_at (numerically equal)
                    if (
                        existing.get("payload") == stored_payload
                        and existing.get("available_at") == available_at
                    ):
                        return _make_public_message(existing)
                raise SpoolError(
                    "IDEMPOTENCY_CONFLICT",
                    f"Message {message_id!r} already exists with different data",
                )

            if len(messages) >= self._limits.max_messages:
                raise SpoolError(
                    "CAPACITY_EXCEEDED",
                    f"Max messages ({self._limits.max_messages}) reached",
                )

            seq = state["next_sequence"]
            msg_data: dict[str, Any] = {
                "message_id": message_id,
                "payload": stored_payload,
                "status": "pending",
                "available_at": available_at,
                "sequence": seq,
                "attempts": 0,
                "last_error": None,
                "worker_id": None,
                "lease_token": None,
                "expires_at": None,
            }
            messages[message_id] = msg_data
            state["next_sequence"] = seq + 1
            self._write_state(state)
        finally:
            self._release_lock()

        return _make_public_message(msg_data)

    def claim(self, worker_id: str) -> dict | None:
        if not _is_nonempty_string(worker_id):
            raise SpoolError("INVALID_INPUT", "worker_id must be a non-empty, non-whitespace string")

        self._acquire_lock()
        try:
            self._call_failpoint("after_lock")
            state = self._read_state()
            now = float(self._validate_clock())

            messages: dict = state["messages"]
            # Find pending messages with available_at <= now
            candidates = []
            for mid, msg in messages.items():
                if msg.get("status") == "pending" and msg.get("available_at", float("inf")) <= now:
                    candidates.append(msg)

            if not candidates:
                return None

            # Sort by (available_at, sequence, message_id)
            candidates.sort(key=_message_sort_key)
            chosen = candidates[0]

            # Generate lease token
            lease_token = secrets.token_hex(16)
            expires_at = now + self._limits.lease_seconds

            chosen["status"] = "leased"
            chosen["attempts"] = chosen.get("attempts", 0) + 1
            chosen["worker_id"] = worker_id
            chosen["lease_token"] = lease_token
            chosen["expires_at"] = expires_at

            self._write_state(state)

            result = _make_public_message(chosen)
            result["lease_token"] = lease_token  # type: ignore[assignment]
            return result
        finally:
            self._release_lock()

    def ack(self, message_id: str, lease_token: str) -> dict:
        if not _is_nonempty_string(message_id):
            raise SpoolError("INVALID_INPUT", "message_id must be a non-empty, non-whitespace string")
        if not isinstance(lease_token, str):
            raise SpoolError("INVALID_INPUT", "lease_token must be a string")

        self._acquire_lock()
        try:
            self._call_failpoint("after_lock")
            state = self._read_state()
            messages: dict = state["messages"]

            if message_id not in messages:
                raise SpoolError("NOT_FOUND", f"Message not found: {message_id}")

            msg = messages[message_id]
            if msg.get("status") != "leased":
                raise SpoolError("UNAUTHORIZED", "unauthorized")

            expected = msg.get("lease_token", "")
            if not _constant_time_compare(str(expected), lease_token):
                raise SpoolError("UNAUTHORIZED", "unauthorized")

            msg["status"] = "acked"
            msg["worker_id"] = None
            msg["lease_token"] = None
            msg["expires_at"] = None

            self._write_state(state)
            return _make_public_message(msg)
        finally:
            self._release_lock()

    def fail(self, message_id: str, lease_token: str, error: str) -> dict:
        if not _is_nonempty_string(message_id):
            raise SpoolError("INVALID_INPUT", "message_id must be a non-empty, non-whitespace string")
        if not isinstance(lease_token, str):
            raise SpoolError("INVALID_INPUT", "lease_token must be a string")
        if not _is_nonempty_string(error):
            raise SpoolError("INVALID_INPUT", "error must be a non-empty, non-whitespace string")

        self._acquire_lock()
        try:
            self._call_failpoint("after_lock")
            state = self._read_state()
            messages: dict = state["messages"]

            if message_id not in messages:
                raise SpoolError("NOT_FOUND", f"Message not found: {message_id}")

            msg = messages[message_id]
            if msg.get("status") != "leased":
                raise SpoolError("UNAUTHORIZED", "unauthorized")

            expected = msg.get("lease_token", "")
            if not _constant_time_compare(str(expected), lease_token):
                raise SpoolError("UNAUTHORIZED", "unauthorized")

            msg["last_error"] = error
            msg["worker_id"] = None
            msg["lease_token"] = None
            msg["expires_at"] = None

            attempts = msg.get("attempts", 0)
            if attempts >= self._limits.max_attempts:
                msg["status"] = "dead"
            else:
                msg["status"] = "pending"
                msg["available_at"] = float(self._validate_clock()) + self._limits.retry_delay

            self._write_state(state)
            return _make_public_message(msg)
        finally:
            self._release_lock()

    def recover(self) -> dict:
        self._acquire_lock()
        try:
            self._call_failpoint("after_lock")
            state = self._read_state()
            now = float(self._validate_clock())

            messages: dict = state["messages"]
            recovered = 0

            for msg in messages.values():
                if msg.get("status") != "leased":
                    continue
                expires_at = msg.get("expires_at")
                if expires_at is None or not (now >= expires_at):
                    continue

                msg["worker_id"] = None
                msg["lease_token"] = None
                msg["expires_at"] = None

                attempts = msg.get("attempts", 0)
                if attempts >= self._limits.max_attempts:
                    msg["status"] = "dead"
                else:
                    msg["status"] = "pending"
                    msg["available_at"] = now
                recovered += 1

            if recovered > 0:
                self._write_state(state)

            return {"recovered": recovered}
        finally:
            self._release_lock()

    def get(self, message_id: str) -> dict:
        if not _is_nonempty_string(message_id):
            raise SpoolError("INVALID_INPUT", "message_id must be a non-empty, non-whitespace string")

        self._acquire_lock()
        try:
            state = self._read_state()
            messages: dict = state["messages"]
            if message_id not in messages:
                raise SpoolError("NOT_FOUND", f"Message not found: {message_id}")
            return _make_public_message(messages[message_id])
        finally:
            self._release_lock()

    def list_messages(self, status=None) -> list[dict]:
        if status is not None:
            if not isinstance(status, str) or status not in _VALID_STATUSES:
                raise SpoolError("INVALID_INPUT", f"Invalid status: {status!r}")

        self._acquire_lock()
        try:
            state = self._read_state()
            messages: dict = state["messages"]
            result = []
            for msg in messages.values():
                if status is None or msg.get("status") == status:
                    result.append(msg)
            result.sort(key=_message_sort_key)
            return [_make_public_message(m) for m in result]
        finally:
            self._release_lock()

    # ---- Private helpers ----

    def _validate_clock(self) -> float:
        try:
            ts = self._clock()
        except Exception as exc:
            raise SpoolError("INVALID_DEPENDENCY", f"clock() raised: {exc}") from exc
        if isinstance(ts, bool) or not isinstance(ts, (int, float)):
            raise SpoolError("INVALID_DEPENDENCY", "clock() must return a finite number")
        if not isfinite(ts):
            raise SpoolError("INVALID_DEPENDENCY", "clock() must be finite")
        return float(ts)


def _validate_message_data(message_id: str, msg: dict) -> None:
    """Validate a single message record from state. Raises CORRUPT_STATE."""
    allowed_fields = {
        "message_id", "payload", "status", "available_at",
        "sequence", "attempts", "last_error",
        "worker_id", "lease_token", "expires_at",
    }
    extra = set(msg.keys()) - allowed_fields
    if extra:
        raise SpoolError("CORRUPT_STATE", f"Message {message_id}: unknown fields {extra}")

    # Validate message_id matches key
    stored_id = msg.get("message_id")
    if stored_id != message_id:
        raise SpoolError("CORRUPT_STATE", f"Message {message_id}: message_id mismatch")

    status = msg.get("status")
    if status not in _VALID_STATUSES:
        raise SpoolError("CORRUPT_STATE", f"Message {message_id}: invalid status {status!r}")

    # Validate sequence
    seq = msg.get("sequence")
    if isinstance(seq, bool) or not isinstance(seq, int) or seq < 1:
        raise SpoolError("CORRUPT_STATE", f"Message {message_id}: invalid sequence")

    # Validate attempts
    attempts = msg.get("attempts", 0)
